 if(!product)return <section className="inventory-panel"><button className="inventory-product-back" type="button" onClick={onBack}>← Volver a existencias</button><p>No encontramos ese producto.</p></section>;
 const nodeDetails=nodes.map(node=>{const stock=product.nodes[node.id],lots=getMockProductLots(product,{...node,...stock}),availability=calculateAvailableInventory(lots,stock.reserved),minimum=resolveInventoryMinimum({configuredMinimum:stock.minimum}),statusTags=getNodeStatusTags(lots,stock.reserved,minimum),sales=product.sales.filter(sale=>sale.nodeId===node.id&&(!dateFrom||sale.date>=dateFrom)&&(!dateTo||sale.date<=dateTo)),rotation=sales.reduce((sum,sale)=>sum+sale.quantity,0),averageInventory=stock.averageInventory??stock.physical,rangeDays=getInventoryRangeDays(product.sales.filter(sale=>sale.nodeId===node.id),dateFrom,dateTo);return {...node,...stock,...availability,minimum,statusTags,lots,available:availability.available,rotation,averageInventory,turnover:averageInventory>0?rotation/averageInventory:0,dailyAverage:rangeDays>0?rotation/rangeDays:0,value:stock.physical*product.unitCost,location:getMockProductLocation(product,node),lotCode:getMockBatchCode(product,node.id)}});
