 const filteredRows=rows.filter(product=>normalizeInventorySearch(`${product.name} ${product.sku} ${product.category}`).includes(normalizedQuery)&&(!selectedStatus||(selectedStatus==='Normal'?product.status.label==='Normal':product.status.label==='Requiere atención')));
