  const startLogin=()=>beginInventoryLogin().catch(error=>setReceiptSession(current=>({...current,status:'error',error:sessionErrorMessage(error)})));
  const selectTenant=async tenantId=>{setReceiptSession(current=>({...current,status:'loading'}));try{const selected=await selectInventoryTenant(receiptSession.spaces,tenantId);setReceiptSession(current=>({...current,status:'signed-in',...selected}));}catch(error){setReceiptSession(current=>({...current,status:'error',error:sessionErrorMessage(error)}));}};
  const selectCompany=companyId=>{try{selectInventoryCompany(receiptSession.context,receiptSession.tenantId,companyId);setReceiptSession(current=>({...current,companyId}));}catch(error){setReceiptSession(current=>({...current,error:sessionErrorMessage(error)}));}};
  const signOut=()=>{setReceiptSession({status:'signed-out',spaces:[],tenantId:'',context:null,companyId:''});endInventorySession();};
